using System;
using System.Collections.Generic;
using UnityEngine;

namespace FoveAI
{
    /// <summary>
    /// FuiPalette — the canonical FUI color language inside Unity.
    /// Loaded from Resources/fui_palette.bytes (generated by
    /// `python3 runtime/fui_colors.py` — the single source of truth).
    /// Rule: colors mean state or identity, never decoration. Guiding
    /// colors only; the canvas stays calm.
    /// Fallback values mirror the canonical palette verbatim for the
    /// window before the file loads (and for builds without it).
    /// </summary>
    public static class FuiPalette
    {
        public static event Action Loaded;

        private static Dictionary<string, Color> _states = new Dictionary<string, Color>(StringComparer.OrdinalIgnoreCase)
        {
            { "ok",      Hex("#00E664") },
            { "busy",    Hex("#FF9E1F") },
            { "warn",    Hex("#FFE600") },
            { "crit",    Hex("#FF3232") },
            { "idle",    Hex("#888888") },
            { "info",    Hex("#00DCFF") },
            { "select",  Hex("#00DCFF") },
        };

        private static Dictionary<string, Color> _archetypes = new Dictionary<string, Color>(StringComparer.OrdinalIgnoreCase)
        {
            { "companion", Hex("#FF3232") },
            { "friend",    Hex("#FFE600") },
            { "beloved",   Hex("#FF3CC8") },
            { "tool",      Hex("#00E664") },
            { "inventor",  Hex("#00DCFF") },
            { "assistant", Hex("#5FAFFF") },
        };

        private static bool _loaded;

        /// <summary>State color by role (ok/busy/warn/crit/idle/info/select).</summary>
        public static Color State(string name)
        {
            EnsureLoaded();
            return _states.TryGetValue(name, out var c) ? c : _states["idle"];
        }

        /// <summary>Archetype identity color (companion/friend/beloved/tool/inventor/assistant).</summary>
        public static Color Archetype(string cid)
        {
            EnsureLoaded();
            return _archetypes.TryGetValue(cid, out var c) ? c : _archetypes["inventor"];
        }

        private static void EnsureLoaded()
        {
            if (_loaded) return;
            _loaded = true;
            try
            {
                // Android: Resources survive StreamingAssets' path differences
                var asset = Resources.Load<TextAsset>("fui_palette");
                if (asset == null) return;
                var root = JsonUtility.FromJson<FuiJson>(asset.text);
                if (root?.unity?.states != null && root.unity.states.Length > 0)
                {
                    foreach (var s in root.unity.states)
                    {
                        var c = Hex(s.hex);
                        if (!string.IsNullOrEmpty(s.hex))
                            _states[s.key] = c;
                    }
                    foreach (var a in root.unity.archetypes)
                    {
                        if (!string.IsNullOrEmpty(a.hex))
                            _archetypes[a.key] = Hex(a.hex);
                    }
                    Debug.Log($"[FuiPalette] canonical palette loaded " +
                              $"({root.unity.states.Length} states, {root.unity.archetypes.Length} archetypes)");
                    Loaded?.Invoke();
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[FuiPalette] load failed — canonical fallbacks stand: {e.Message}");
            }
        }

        [Serializable]
        private class FuiJson
        {
            public UnityView unity;
        }

        [Serializable]
        private class UnityView
        {
            public FuiEntry[] states;
            public FuiEntry[] archetypes;
        }

        [Serializable]
        private class FuiEntry
        {
            public string key;
            public string hex;
        }

        private static Color Hex(string s)
        {
            try
            {
                if (string.IsNullOrEmpty(s) || s[0] != '#' || s.Length < 7) return Color.magenta;
                var r = Convert.ToInt32(s.Substring(1, 2), 16) / 255f;
                var g = Convert.ToInt32(s.Substring(3, 2), 16) / 255f;
                var b = Convert.ToInt32(s.Substring(5, 2), 16) / 255f;
                return new Color(r, g, b, 1f);
            }
            catch { return Color.magenta; }
        }
    }
}